"use client";

import { useMemo, useState } from "react";
import { INGESTED_DATA } from "@/lib/data/ingestedData";
import { answerDemoQuestion } from "@/lib/ai/mockAdvisor";

type Product = (typeof INGESTED_DATA.products)[number];
type View = "Dashboard" | "Explorer" | "Compare" | "Saved" | "Insights" | "Messaging" | "Advisor" | "Battlecards" | "Assets" | "Sources" | "Admin";

const nav: { label: View; icon: string; title: string }[] = [
  { label: "Dashboard", title: "Dashboard", icon: "◫" }, { label: "Compare", title: "Compare Products", icon: "⇄" },
  { label: "Explorer", title: "Product Explorer", icon: "⌕" }, { label: "Saved", title: "Saved Comparisons", icon: "♡" },
];
const key = (product: Product, label: string): string => (product.attributes as Record<string, string>)[label] ?? "Information unavailable";
const short = (value: string) => value.replace("Up to ", "≤ ").replace("Extremely Quiet, ", "");
const isDaikin = (product: Product) => product.brand === "Daikin";

function Logo() { return <div className="brand-mark" aria-label="Daikin logo placeholder"><i /> <span>DAIKIN</span></div>; }
function Source({ children }: { children: React.ReactNode }) { return <span className="source">⊙ {children}</span>; }

function Metric({ label, value, note }: { label: string; value: string | number; note: string }) {
  return <article className="metric"><span>{label}</span><strong>{value}</strong><small>{note}</small></article>;
}

const tonnageOptions = (product: Product): string[] => {
  const raw = key(product, "Tonnage options");
  if (raw === "Information unavailable") return [];
  return [...new Set(raw.match(/\d+(?:\.\d+)?/g) ?? [])].map((size) => `${size} Ton`);
};
const sourcePreview = (product: Product) => key(product, "SEER2") !== "Information unavailable" ? `SEER2 ${short(key(product, "SEER2"))}` : short(key(product, "Sound level"));

function SimpleDashboard({ products, selected, units, toggle, setUnit, setView }: { products: readonly Product[]; selected: string[]; units: Record<string, string>; toggle: (id: string) => void; setUnit: React.Dispatch<React.SetStateAction<Record<string, string>>>; setView: (view: View) => void }) {
  return <div className="page simple-dashboard"><section className="builder-hero"><p className="eyebrow">DAIKIN COMPETITIVE MARKETING INTELLIGENCE</p><h1>Which products would you like to compare?</h1><p>Search once across Daikin and competitor models, select units where source data supports them, then compare.</p><SmartSearch products={products} selected={selected} units={units} toggle={toggle} setUnit={setUnit} onCompare={() => setView("Compare")} /></section><section className="quick-grid"><article className="panel"><p className="eyebrow">RECENTLY COMPARED</p><h2>Daikin FIT vs. Bosch IDS</h2><p>Start from a familiar competitive set or build a new comparison above.</p><button className="text-button" onClick={() => setView("Compare")}>Open comparison →</button></article><article className="panel"><p className="eyebrow">STRONGEST DIFFERENTIATORS</p><h2>Warranty, controls, installation</h2><p>See only source-backed claims and validation gaps in the comparison dashboard.</p><button className="text-button" onClick={() => setView("Compare")}>View evidence →</button></article><article className="panel"><p className="eyebrow">PRODUCT DATA COVERAGE</p><h2>{products.length} products, 2 sources</h2><p>Blank fields remain unavailable - never inferred as a product limitation.</p><Source>Imported source lineage</Source></article></section></div>;
}

function SmartSearch({ products, selected, units, toggle, setUnit, onCompare }: { products: readonly Product[]; selected: string[]; units: Record<string, string>; toggle: (id: string) => void; setUnit: React.Dispatch<React.SetStateAction<Record<string, string>>>; onCompare: () => void }) {
  const [term, setTerm] = useState(""); const [active, setActive] = useState(0); const [recent, setRecent] = useState<string[]>([]);
  const normalized = term.toLowerCase().replace(/[\s-]/g, "");
  const matching = products.filter((product) => {
    const haystack = `${product.brand} ${product.model} ${product.family} ${product.equipmentType} ${Object.values(product.attributes).join(" ")}`.toLowerCase().replace(/[\s-]/g, "");
    return !term || haystack.includes(normalized) || (normalized === "quiet" && key(product, "Sound level") !== "Information unavailable");
  }).slice(0, 10);
  const daikin = matching.filter(isDaikin); const competitors = matching.filter((product) => !isDaikin(product));
  function choose(product: Product) { if (!selected.includes(product.id)) toggle(product.id); setRecent((current) => [product.model, ...current.filter((item) => item !== product.model)].slice(0, 3)); setTerm(""); }
  function keydown(event: React.KeyboardEvent<HTMLInputElement>) { if (event.key === "ArrowDown") { event.preventDefault(); setActive((current) => Math.min(current + 1, Math.max(matching.length - 1, 0))); } if (event.key === "ArrowUp") { event.preventDefault(); setActive((current) => Math.max(current - 1, 0)); } if (event.key === "Enter" && matching[active]) { event.preventDefault(); choose(matching[active]); } }
  return <div className="smart-builder"><div className="smart-search"><span>⌕</span><input autoFocus value={term} onKeyDown={keydown} onChange={(event) => { setTerm(event.target.value); setActive(0); }} placeholder="Search Daikin or competitor products by brand, family, model, tonnage, refrigerant, or feature…" aria-label="Search products to compare" /><kbd>⌘ K</kbd></div>{term && <div className="suggestions" role="listbox"><SuggestionGroup title="Daikin products" products={daikin} active={active} all={matching} choose={choose} term={term} /><SuggestionGroup title="Competitor products" products={competitors} active={active} all={matching} choose={choose} term={term} /><div className="suggestion-meta"><span>BRANDS</span>{[...new Set(matching.map((product) => product.brand))].slice(0, 5).map((brand) => <button key={brand} onClick={() => setTerm(brand)}>{brand}</button>)}<span>PRODUCT FAMILIES</span>{[...new Set(matching.map((product) => product.family))].slice(0, 3).map((family) => <button key={family} onClick={() => setTerm(family)}>{family}</button>)}</div></div>}{!term && <div className="search-hints"><span>Try: <button onClick={() => setTerm("DH7")}>DH7</button><button onClick={() => setTerm("Rheem 18")}>Rheem 18</button><button onClick={() => setTerm("R-32")}>R-32</button><button onClick={() => setTerm("quiet")}>quiet</button></span>{recent.length > 0 && <span>Recent: {recent.join(" • ")}</span>}</div>}<div className="selected-strip"><div className="selected-head"><b>Selected products</b><span>{selected.length}/8</span>{selected.length > 0 && <button onClick={() => selected.slice().forEach(toggle)}>Clear all</button>}</div>{selected.length === 0 ? <div className="select-empty">Search above to add a Daikin or competitor product. Start with any two products.</div> : <div className="selected-cards">{products.filter((product) => selected.includes(product.id)).map((product) => <article key={product.id}><div><span className={isDaikin(product) ? "brand daikin" : "brand"}>{product.brand}</span><button onClick={() => toggle(product.id)} aria-label={`Remove ${product.model}`}>×</button></div><b>{product.model}</b><small>{product.family}</small>{tonnageOptions(product).length > 0 ? <div className="unit-picker"><span>Unit size</span>{tonnageOptions(product).map((unit) => <button className={units[product.id] === unit ? "unit active" : "unit"} key={unit} onClick={() => setUnit((current) => ({ ...current, [product.id]: unit }))}>{unit}</button>)}</div> : <em>Model-level information only</em>}</article>)}</div>}</div><div className="builder-action"><span>{selected.length < 2 ? "Select at least two products to compare" : "Ready to compare selected products"}</span><button className="primary" disabled={selected.length < 2} onClick={onCompare}>Compare Selected Products <span>→</span></button></div></div>;
}

function SuggestionGroup({ title, products, active, all, choose, term }: { title: string; products: Product[]; active: number; all: Product[]; choose: (product: Product) => void; term: string }) { if (!products.length) return null; return <div className="suggestion-group"><span>{title.toUpperCase()}</span>{products.map((product) => <button className={all.indexOf(product) === active ? "suggestion active" : "suggestion"} key={product.id} onClick={() => choose(product)}><i className={isDaikin(product) ? "dot green" : "dot amber"} /><div><b>{highlight(product.model, term)}</b><small>{product.brand} • {product.family} • {key(product, "Refrigerant")}</small></div><em>{sourcePreview(product)}</em></button>)}</div>; }
function highlight(text: string, term: string) { const position = text.toLowerCase().indexOf(term.toLowerCase()); return position < 0 || !term ? text : <>{text.slice(0, position)}<mark>{text.slice(position, position + term.length)}</mark>{text.slice(position + term.length)}</>; }

function numeric(product: Product, label: string): number | null { const value = key(product, label).replace(/,/g, "").match(/\d+(?:\.\d+)?/); return value ? Number(value[0]) : null; }

type ComparisonSignal = { product: Product; attribute: string; detail: string; action?: string };
const performanceAttributes = ["SEER2", "EER2", "HSPF2", "COP@5F"];
const binaryEdgeAttributes = ["Charge verification without tools (Quality Install)", "Slow loss of charge alerting (Charge Integrity)", "Real-time, cloud-connected, Alerts & Diagnostics (Cloud Services)"];

function hasDaikinEdge(product: Product, competitors: Product[], attribute: string) {
  const value = key(product, attribute);
  const competitorValues = competitors.filter((competitor) => key(competitor, attribute) !== "Information unavailable");
  if (value === "Information unavailable" || !competitorValues.length) return false;
  if (attribute === "Warranty") return (numeric(product, attribute) ?? 0) > Math.max(...competitorValues.map((competitor) => numeric(competitor, attribute) ?? 0));
  if (attribute === "Sound level") return (numeric(product, attribute) ?? Infinity) < Math.min(...competitorValues.map((competitor) => numeric(competitor, attribute) ?? Infinity));
  if (performanceAttributes.includes(attribute)) return (numeric(product, attribute) ?? -Infinity) > Math.max(...competitorValues.map((competitor) => numeric(competitor, attribute) ?? -Infinity));
  if (binaryEdgeAttributes.includes(attribute)) return value === "Yes" && competitorValues.every((competitor) => key(competitor, attribute) === "No");
  if (attribute === "Air Handler Matchup") return value.includes("115") && competitorValues.every((competitor) => !key(competitor, attribute).includes("115"));
  return false;
}

function daikinEdgeSignals(daikin: Product[], competitors: Product[]): ComparisonSignal[] {
  const attributes = ["Warranty", "Sound level", "Air Handler Matchup", ...binaryEdgeAttributes, ...performanceAttributes];
  return daikin.flatMap((product) => attributes.filter((attribute) => hasDaikinEdge(product, competitors, attribute)).map((attribute) => {
    const competitorsWithValues = competitors.filter((competitor) => key(competitor, attribute) !== "Information unavailable");
    const competitorValue = competitorsWithValues[0] ? short(key(competitorsWithValues[0], attribute)) : "Information unavailable";
    const detail = binaryEdgeAttributes.includes(attribute)
      ? `${product.model} lists Yes while every selected competitor with source data lists No.`
      : attribute === "Air Handler Matchup"
        ? `${product.model} lists ${short(key(product, attribute))}; none of the selected competitors list a 115V matchup.`
        : `${product.model} lists ${short(key(product, attribute))}, ahead of the selected competitor values (for example ${competitorValue}).`;
    return { product, attribute, detail };
  }));
}

function daikinImprovementSignals(daikin: Product[], competitors: Product[]): ComparisonSignal[] {
  return daikin.flatMap((product) => [...performanceAttributes, "Sound level"].flatMap((attribute) => {
    const own = numeric(product, attribute);
    const ranked = competitors.filter((competitor) => numeric(competitor, attribute) !== null).sort((a, b) => (numeric(a, attribute) ?? 0) - (numeric(b, attribute) ?? 0));
    if (own === null || !ranked.length) return [];
    const leader = attribute === "Sound level" ? ranked[0] : ranked[ranked.length - 1];
    const competitorValue = numeric(leader, attribute) ?? own;
    const isGap = attribute === "Sound level" ? competitorValue < own : competitorValue > own;
    if (!isGap) return [];
    const action = attribute === "Sound level"
      ? "Improvement focus: investigate quieter performance in the relevant product/application, and avoid a blanket quietest claim."
      : "Improvement focus: address the performance gap in product/portfolio planning; keep current efficiency claims model-specific.";
    return [{ product, attribute, detail: `${leader.model} lists ${short(key(leader, attribute))}, compared with ${product.model} at ${short(key(product, attribute))}.`, action }];
  }));
}

function AnalyticsComparison({ comparison, units, toggle, setView }: { comparison: Product[]; units: Record<string, string>; toggle: (id: string) => void; setView: (view: View) => void }) {
  const [filter, setFilter] = useState("All Attributes");
  if (comparison.length < 2) return <div className="page"><section className="empty analytical-empty"><h1>Select products to start a comparison.</h1><p>Use the Dashboard search to choose two to eight Daikin or competitor products.</p><button className="primary" onClick={() => setView("Dashboard")}>Go to Dashboard <span>→</span></button></section></div>;
  const daikin = comparison.filter(isDaikin); const competitors = comparison.filter((product) => !isDaikin(product));
  const edgeSignals = daikinEdgeSignals(daikin, competitors);
  const improvementSignals = daikinImprovementSignals(daikin, competitors);
  const uniqueEdgeSignals = edgeSignals.filter((signal, index, signals) => signals.findIndex((candidate) => candidate.attribute === signal.attribute) === index);
  const uniqueImprovementSignals = improvementSignals.filter((signal, index, signals) => signals.findIndex((candidate) => candidate.attribute === signal.attribute) === index);
  const attributes = ["Refrigerant", "SEER2", "EER2", "HSPF2", "COP@5F", "Sound level", "Heating operating range", "Air Handler Matchup", "Compressor Type", "Warranty", "Charge verification without tools (Quality Install)", "Slow loss of charge alerting (Charge Integrity)", "Real-time, cloud-connected, Alerts & Diagnostics (Cloud Services)"];
  const visible = attributes.filter((attribute) => {
    const values = comparison.map((product) => key(product, attribute));
    if (filter === "Missing Data") return values.includes("Information unavailable");
    if (filter === "Daikin Advantages") return edgeSignals.some((signal) => signal.attribute === attribute);
    if (filter === "Differences Only") return new Set(values).size > 1;
    return true;
  });
  return <div className="page analytical"><section className="comparison-overview"><div><p className="eyebrow">DAIKIN-LED COMPARISON</p><h1>Where Daikin wins — and where to improve.</h1><p>Model-level comparison{Object.values(units).some(Boolean) ? " with selected source-supported unit sizes" : ""}. Daikin edges are calculated only against the products selected here.</p></div><button className="secondary" onClick={() => setView("Dashboard")}>← Edit selection</button></section><section className="selected-summary">{comparison.map((product) => <article className={isDaikin(product) ? "selected-summary-card daikin-card" : "selected-summary-card"} key={product.id}><span className={isDaikin(product) ? "brand daikin" : "brand"}>{product.brand}</span><b>{product.model}</b><small>{units[product.id] ?? "Model-level information only"}</small><div><span>{key(product, "Refrigerant")}</span><span>{short(key(product, "SEER2"))}</span><span>{short(key(product, "Sound level"))}</span></div><button onClick={() => toggle(product.id)}>Remove</button></article>)}</section><section className="summary-cards"><Metric label="Verified Daikin edges" value={uniqueEdgeSignals.length} note="Distinct capabilities vs. selected competitors" /><Metric label="Improvement gaps" value={uniqueImprovementSignals.length} note="Distinct source-listed gaps" /><Metric label="Attributes compared" value={visible.length} note="Model-level values retained" /><Metric label="Data confidence" value="86%" note="Blank fields remain unavailable" /></section><section className="ai-insights"><div className="section-heading"><div><p className="eyebrow">DAIKIN POSITIONING SUMMARY</p><h2>Lead with proof. Improve with context.</h2></div><Source>Every detected Daikin edge is listed below</Source></div><div className="insight-grid">{uniqueEdgeSignals.map((signal) => <Insight key={`${signal.product.id}-${signal.attribute}`} tone="green" title={`Daikin edge: ${signal.attribute}`} text={signal.detail} source={signal.product.source} tag="VERIFIED DAIKIN EDGE" />)}{uniqueImprovementSignals.map((signal) => <Insight key={`${signal.product.id}-${signal.attribute}`} tone="amber" title={`Improve: ${signal.attribute}`} text={`${signal.detail} ${signal.action}`} source={`${signal.product.source} • ${signal.attribute}`} tag="COMPETITIVE GAP / ACTION" />)}{!edgeSignals.length && <Insight tone="blue" title="No proven Daikin edge in this selection" text="Add a Daikin product and competitors with comparable source values to surface a defensible advantage. Missing source data is not treated as a loss." source="Selected product records" tag="INFORMATION UNAVAILABLE" />}{comparison.some((product) => attributes.some((attribute) => key(product, attribute) === "Information unavailable")) && <Insight tone="red" title="Validate missing comparison data" text="Some selected values are unavailable. Do not convert blanks, formula errors, or incomparable conditions into a Daikin weakness or competitive claim." source="Imported source quality rules" tag="VALIDATION REQUIRED" />}</div></section><section className="charts"><div className="section-heading"><div><p className="eyebrow">INTERACTIVE COMPARISON CHARTS</p><h2>Performance in context</h2></div><span className="chip">Only source-supported metrics shown</span></div><div className="chart-grid"><MetricBars title="Efficiency comparison" subtitle="Higher is generally better" products={comparison} labels={["SEER2", "HSPF2", "COP@5F"]} /><MetricBars title="Sound performance" subtitle="Lower dBA is better" products={comparison.filter((product) => numeric(product, "Sound level") !== null)} labels={["Sound level"]} invert /><RangeChart products={comparison.filter((product) => key(product, "Heating operating range") !== "Information unavailable")} /><MetricBars title="Warranty coverage" subtitle="Years shown when included in source" products={comparison} labels={["Warranty"]} /></div></section><section className="scorecards"><div className="section-heading"><div><p className="eyebrow">KEY ADVANTAGE SCORECARDS</p><h2>Fast answers for the team</h2></div></div><div><Scorecard title="Efficiency Leader" product={bestOf(comparison, "SEER2", "higher")} reason="Highest listed SEER2 in the selected source records." /><Scorecard title="Quietest Product" product={bestOf(comparison, "Sound level", "lower")} reason="Lowest listed approximate sound level." /><Scorecard title="Best Warranty" product={bestOf(comparison, "Warranty", "higher")} reason="Longest listed warranty term in the selected source records." /><Scorecard title="Daikin Edge to Lead" product={uniqueEdgeSignals[0]?.product ?? null} reason={uniqueEdgeSignals[0] ? `${uniqueEdgeSignals[0].attribute}: ${uniqueEdgeSignals[0].detail}` : "No source-proven Daikin edge in this product selection."} /></div></section><section className="panel comparison-table analytical-table"><div className="panel-head"><div><p className="eyebrow">DETAILED FEATURE COMPARISON</p><h2>Evidence at attribute level</h2></div><div>{["All Attributes", "Differences Only", "Daikin Advantages", "Missing Data"].map((item) => <button key={item} className={filter === item ? "filter active" : "filter"} onClick={() => setFilter(item)}>{item}</button>)}</div></div><div className="table-scroll"><table><thead><tr><th>Feature</th>{comparison.map((product) => <th key={product.id}><span className={isDaikin(product) ? "brand daikin" : "brand"}>{product.brand}</span><b>{product.model}</b><small>{units[product.id] ?? "Model"}</small></th>)}</tr></thead><tbody>{visible.map((attribute) => <tr key={attribute}><th>{attribute}<small>Source-backed value</small></th>{comparison.map((product) => { const value = key(product, attribute); const advantage = isDaikin(product) && hasDaikinEdge(product, competitors, attribute); return <td className={advantage ? "advantage-cell" : value === "Information unavailable" ? "unknown-cell" : ""} key={product.id}>{advantage && <em>Verified Daikin edge</em>}<b>{short(value)}</b><Source>{product.source}</Source></td>; })}</tr>)}</tbody></table></div></section><MarketingTakeaways daikin={daikin[0] ?? null} competitors={competitors} /></div>;
}

function MetricBars({ title, subtitle, products, labels, invert = false }: { title: string; subtitle: string; products: Product[]; labels: string[]; invert?: boolean }) { if (!products.length) return null; return <article className="panel chart-card"><h3>{title}</h3><p>{subtitle}</p>{products.map((product) => { const values = labels.map((label) => numeric(product, label)).filter((value): value is number => value !== null); if (!values.length) return null; const score = invert ? Math.max(15, 100 - Math.min(values[0], 80)) : Math.min(100, Math.max(...values) * (labels.includes("COP@5F") ? 35 : 5)); return <div className="chart-row" key={product.id}><span>{product.model}</span><div><i className={isDaikin(product) ? "daikin-line" : ""} style={{ width: `${score}%` }} /></div><b>{labels.map((label) => short(key(product, label))).join(" · ")}</b></div>; })}<Source>Selected product source records</Source></article>; }
function RangeChart({ products }: { products: Product[] }) { if (!products.length) return null; return <article className="panel chart-card"><h3>Heating operating range</h3><p>Lower minimum temperature extends cold-weather range.</p>{products.map((product) => <div className="chart-row" key={product.id}><span>{product.model}</span><div><i className={isDaikin(product) ? "daikin-line" : ""} style={{ width: "72%" }} /></div><b>{key(product, "Heating operating range")}</b></div>)}<Source>Heating Operating Range • Battlecard p. 1</Source></article>; }
function bestOf(products: Product[], label: string, direction: "higher" | "lower") { const valid = products.filter((product) => numeric(product, label) !== null); if (!valid.length) return null; return valid.sort((a, b) => ((numeric(a, label) ?? 0) - (numeric(b, label) ?? 0)) * (direction === "higher" ? -1 : 1))[0]; }
function Scorecard({ title, product, reason }: { title: string; product: Product | null; reason: string }) { return <article><span>{title}</span><b>{product?.model ?? "Insufficient Data"}</b><p>{product ? reason : "Source information unavailable for the selected products."}</p><Source>{product?.source ?? "Information unavailable"}</Source></article>; }
function MarketingTakeaways({ daikin, competitors }: { daikin: Product | null; competitors: Product[] }) { const [copied, setCopied] = useState(""); const messages = ["VERIFIED FACT: Listed Daikin FIT variants have R-32 and 115V / 240V air-handler matchup in the source battlecard.", "COMPETITIVE INTERPRETATION: Lead with installation flexibility, controls, and warranty where they match the conversation.", "SUGGESTED MARKETING MESSAGE: ‘Make every Daikin product conversation more defensible with verified proof points.’", `CLAIM REQUIRING VALIDATION: ${competitors[0]?.model ?? "Competitor"} may have a selected efficiency advantage; validate model-level context before external use.`]; return <section className="takeaways"><div className="section-heading"><div><p className="eyebrow">MARKETING TAKEAWAYS</p><h2>Simple, source-aware direction</h2></div><span className="chip green-chip">{daikin?.model ?? "Daikin"} focus</span></div><div>{messages.map((message, index) => <article key={message}><span className={index === 0 ? "claim-label fact" : index === 3 ? "claim-label validation" : "claim-label recommendation"}>{message.split(":")[0]}</span><p>{message.slice(message.indexOf(":") + 1).trim()}</p><button className="text-button" onClick={() => { void navigator.clipboard?.writeText(message); setCopied(message); }}>{copied === message ? "Copied" : "Copy"}</button><Source>{index === 3 ? "Selected source comparison" : "Daikin FIT Battlecard.pdf • p. 1"}</Source></article>)}</div></section>; }

export default function Home() {
  const [authenticated, setAuthenticated] = useState(false);
  const [view, setView] = useState<View>("Dashboard");
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState<string[]>(["fit-1", "fit-2", "fit-13"]);
  const [chatOpen, setChatOpen] = useState(false);
  const [chat, setChat] = useState("What are the strongest verified differentiators for Daikin FIT?");
  const [submitted, setSubmitted] = useState(false);
  const [email, setEmail] = useState("demo@daikin.com");
  const [password, setPassword] = useState("DaikinDemo2026!");
  const [loginError, setLoginError] = useState("");
  const [unitSelections, setUnitSelections] = useState<Record<string, string>>({});
  const filtered = useMemo(() => INGESTED_DATA.products.filter((product) =>
    `${product.brand} ${product.model} ${product.family}`.toLowerCase().includes(query.toLowerCase())), [query]);
  const comparison = useMemo(() => INGESTED_DATA.products.filter((product) => selected.includes(product.id)), [selected]);
  const answer = submitted ? answerDemoQuestion(chat) : null;

  function login() {
    if (email.toLowerCase() === "demo@daikin.com" && password === "DaikinDemo2026!") { setAuthenticated(true); setLoginError(""); }
    else setLoginError("Use the configured competition demo credentials to continue.");
  }
  function toggle(id: string) { setSelected((current) => current.includes(id) ? current.filter((item) => item !== id) : current.length < 8 ? [...current, id] : current); }
  if (!authenticated) return <Login email={email} password={password} setEmail={setEmail} setPassword={setPassword} error={loginError} login={login} />;

  return <main className="app-shell">
    <aside className="sidebar"><Logo /><div className="workspace-pill"><span className="pulse" /> COMPETITIVE INTELLIGENCE</div>
      <nav aria-label="Primary navigation">{nav.map((item) => <button className={view === item.label ? "nav-item active" : "nav-item"} onClick={() => setView(item.label)} key={item.label}><b>{item.icon}</b>{item.title}</button>)}</nav>
      <div className="sidebar-foot"><span>Data is source-backed</span><strong>2 sources • {INGESTED_DATA.products.length} products</strong></div>
    </aside>
    <section className="content"><header className="topbar"><div className="crumb"><span>Competitive Intelligence</span><b>/{nav.find((item) => item.label === view)?.title}</b></div><label className="search"><span>⌕</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search product data..." /></label><button className="round" aria-label="Notifications">◌</button><button className="avatar" aria-label="Demo user">DS</button></header>
      {view === "Dashboard" && <SimpleDashboard products={INGESTED_DATA.products} selected={selected} units={unitSelections} toggle={toggle} setUnit={setUnitSelections} setView={setView} />}
      {view === "Explorer" && <Explorer products={filtered} selected={selected} toggle={toggle} />}
      {view === "Compare" && <AnalyticsComparison comparison={comparison} units={unitSelections} toggle={toggle} setView={setView} />}
      {view === "Insights" && <Insights />}
      {view === "Messaging" && <Messaging selected={comparison} />}
      {view === "Advisor" && <Advisor chat={chat} setChat={setChat} submitted={submitted} submit={() => setSubmitted(true)} answer={answer} />}
      {view === "Battlecards" && <Battlecards products={comparison.length ? comparison : INGESTED_DATA.products.slice(0, 4)} />}
      {view === "Assets" && <CampaignAssets selected={comparison} />}
      {view === "Saved" && <Saved selected={comparison} />}
      {view === "Sources" && <Sources />}
      {view === "Admin" && <Admin />}
    </section>
    <button className="floating" onClick={() => setChatOpen(!chatOpen)} aria-label="Toggle AI advisor">✦</button>
    {chatOpen && <aside className="chat"><div className="chat-head"><div><span>AI COMPETITIVE ADVISOR</span><strong>Evidence-led comparison support</strong></div><button onClick={() => setChatOpen(false)}>×</button></div><div className="chat-body"><p className="assistant-bubble">{comparison.length ? `Current comparison: ${comparison.map((product) => product.model).join(" • ")}. Ask about advantages, warranties, sound, cold climate, or defensible messages.` : "Select two products and I’ll use them as comparison context."}</p>{answer && <><p className="assistant-bubble answer">{answer.answer}</p><Source>{answer.citations[0]}</Source></>}</div><form onSubmit={(event) => { event.preventDefault(); setSubmitted(true); }}><input value={chat} onChange={(event) => setChat(event.target.value)} aria-label="Ask the AI competitive advisor" /><button>↗</button></form></aside>}
  </main>;
}

function Login({ email, password, setEmail, setPassword, error, login }: { email: string; password: string; setEmail: (value: string) => void; setPassword: (value: string) => void; error: string; login: () => void }) {
  const [show, setShow] = useState(false);
  return <main className="login"><div className="login-orbit orbit-a" /><div className="login-orbit orbit-b" /><section className="login-copy"><Logo /><p className="eyebrow">DAIKIN COMPETITIVE MARKETING INTELLIGENCE</p><h1>Turn verified product intelligence into <br />market momentum.</h1><p>Compare. Position. Win.</p><div className="login-proof"><span>28 <small>products</small></span><span>2 <small>verified sources</small></span><span>∞ <small>stronger stories</small></span></div></section><section className="signin"><div><p className="eyebrow">SECURE DEMO ACCESS</p><h2>Welcome back</h2><p>Build your next competitive advantage.</p></div><label>Email<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} /></label><label>Password<div className="password"><input type={show ? "text" : "password"} value={password} onChange={(event) => setPassword(event.target.value)} /><button type="button" onClick={() => setShow(!show)}>{show ? "Hide" : "Show"}</button></div></label><div className="remember"><label><input type="checkbox" defaultChecked /> Remember me</label><button type="button">Forgot password?</button></div>{error && <p className="form-error">{error}</p>}<button className="primary login-button" onClick={login}>Sign in <span>→</span></button><button className="demo-login" onClick={login}>Use competition demo</button><p className="legal">Demo mode uses a local session. Enterprise SSO is designed as a drop-in replacement.</p></section></main>;
}

// Retained as the prior dashboard reference while the marketing dashboard is active.
