function Overview({ setView, products }: { setView: (view: View) => void; products: readonly Product[] }) {
  const daikin = products.filter(isDaikin).length; const brands = new Set(products.map((product) => product.brand)).size;
  return <div className="page overview"><section className="hero"><div><p className="eyebrow">EXECUTIVE OVERVIEW <span>LIVE DEMO DATA</span></p><h1>Know every advantage before the <em>conversation</em> begins.</h1><p className="lead">A source-grounded command center for product, competitive, and sales intelligence.</p><div className="button-row"><button className="primary" onClick={() => setView("Compare")}>Start a comparison <span>→</span></button><button className="secondary" onClick={() => setView("Advisor")}>✦ Ask the AI advisor</button></div></div><div className="hero-insight"><span className="spark">✦</span><p>AI EXECUTIVE SUMMARY</p><h3>Daikin FIT leads the source set with R-32 coverage, 115V air-handler compatibility and 12-year replacement warranty.</h3><Source>FIT Battlecard • p. 1</Source></div></section><section className="metrics"><Metric label="Imported products" value={products.length} note={`${daikin} Daikin • ${products.length - daikin} competitor`} /><Metric label="Competitor brands" value={brands - 1} note="Across two product families" /><Metric label="Source attributes" value="39" note="Raw values retain provenance" /><Metric label="Verified coverage" value="86%" note="Visible source location" /></section><section className="overview-grid"><article className="panel advantage"><div className="panel-head"><div><p className="eyebrow">COMPARISON LANDSCAPE</p><h2>Daikin advantage distribution</h2></div><button className="text-button">View methodology →</button></div><div className="donut-wrap"><div className="donut"><b>68<small>%</small></b><span>favorable<br />signals</span></div><div className="legend"><p><i className="dot green" /> Better <b>17</b></p><p><i className="dot amber" /> Equivalent <b>6</b></p><p><i className="dot red" /> Competitor better <b>3</b></p><p><i className="dot gray" /> Unavailable <b>13</b></p></div></div></article><article className="panel position"><div className="panel-head"><div><p className="eyebrow">CATEGORY POSITION</p><h2>Where to lead with confidence</h2></div><span className="chip green-chip">Source-backed</span></div>{[["Controls", 92], ["Warranty", 88], ["Installation", 81], ["Cold climate", 76], ["Efficiency", 71], ["Quiet operation", 69]].map(([label, value]) => <div className="bar-row" key={String(label)}><span>{label}</span><div><i style={{ width: `${value}%` }} /></div><b>{value}</b></div>)}</article><article className="panel leaderboard"><div className="panel-head"><div><p className="eyebrow">EFFICIENCY LEADERBOARD</p><h2>SEER2 at a glance</h2></div><span className="chip">FIT battlecard</span></div><div className="leader-list">{products.filter((product) => key(product, "SEER2") !== "Information unavailable").sort((a, b) => parseFloat(key(b, "SEER2").replace(/[^0-9.]/g, "")) - parseFloat(key(a, "SEER2").replace(/[^0-9.]/g, ""))).slice(0, 5).map((product, index) => <div key={product.id}><span>{index + 1}</span><b>{product.model}</b><i className={isDaikin(product) ? "daikin-line" : ""} /><strong>{short(key(product, "SEER2"))}</strong></div>)}</div></article></section></div>;
}

// Retained as the richer briefing reference; the simple Dashboard is the active home.
